def hash_str(s: str) -> str:
    return hashlib.md5(s.encode()).hexdigest()

def fetch_one(url: str) -> dict | None:
    parsed = newspaper.Article(url)
    try:
        parsed.download(); parsed.parse()
    except Exception:
        return None
    return {
        "id": hash_str(url),
        "url": url,
        "title": parsed.title,
        "text": parsed.text,
        "authors": parsed.authors,
        "published": parsed.publish_date.isoformat() if parsed.publish_date else None,
        "fetched": datetime.now(timezone.utc).isoformat()
    }

def run():
    for category, feeds in FEEDS.items():
        for feed in feeds:
            fp = feedparser.parse(feed)
            for entry in fp.entries[:10]:  # limit per feed
                art = fetch_one(entry.link)
                if not art: continue
                out = DATA_DIR / f"{art['id']}.json"
                if out.exists():
                    continue
                out.write_text(json.dumps({"category": category, **art}, ensure_ascii=False, indent=2))

if __name__ == "__main__":
    run()

