import os
from dotenv import load_dotenv
import openai

# Load environment variables from .env file
load_dotenv()

# Set OpenAI API key from environment variable
openai.api_key = os.getenv("OPENAI_API_KEY")

def summarise(text: str) -> str:
    try:
        response = openai.chat.completions.create(
            model="gpt-4o-mini",  # or "gpt-4o", "gpt-4o-mini" depending on your setup
            messages=[
                {"role": "system", "content": "You are a helpful assistant that summarizes text."},
                {"role": "user", "content": f"Please summarize the following text:\n\n{text}"}
            ],
            max_tokens=150,
            temperature=0.5,
        )
        summary = response.choices[0].message.content.strip()
        return summary
    except Exception as e:
        print(f"Error during summarization: {e}")
        return ""

def run():
    # Example input - replace this with your actual text or input source
    data = {
        "text": "OpenAI has developed GPT models that are state-of-the-art in language understanding."
    }
    summary = summarise(data["text"])
    print("Summary:")
    print(summary)

if __name__ == "__main__":
    run()

